param([string]$BackupTime='02:00')
$ErrorActionPreference='Stop';$root=Split-Path -Parent $PSScriptRoot;$start=Join-Path $root 'Start-ChahinazPOS.bat';$backup=Join-Path $PSScriptRoot 'Backup-ChahinazPOS.ps1';schtasks /Create /TN 'Chahinaz POS Startup' /SC ONLOGON /TR "`"$start`"" /F;if($LASTEXITCODE-ne 0){throw 'Could not install startup task.'};schtasks /Create /TN 'Chahinaz POS Backup' /SC DAILY /ST $BackupTime /TR "powershell.exe -NoProfile -ExecutionPolicy Bypass -File `"$backup`"" /F;if($LASTEXITCODE-ne 0){throw 'Could not install backup task.'};Write-Host 'Startup and daily backup tasks installed.' -ForegroundColor Green
